-- Generated by supabase/scripts/seed.ts from supabase/missions/catalog.pt-PT.json.
-- Do not edit by hand: edit the catalogue and run `npm run seed:build -w @icebreaker/supabase`.

on conflict (id) do update set
  type = excluded.type,
  level = excluded.level,
  tags = excluded.tags,
  message_a = excluded.message_a,
  message_b = excluded.message_b,
  follow_up = excluded.follow_up,
  active = true;

-- Missions removed from the catalogue are deactivated, not deleted (mission_runs reference them).
update public.missions set active = false where id not in ('aa_math_joke', 'aa_weird_week', 'aa_famous_impression', 'aa_childhood_story', 'aa_sell_object', 'aa_day_trailer', 'sm_ananas', 'sm_questions_only', 'sm_hum_a_song', 'sm_penguin', 'sm_high_five', 'sm_mirror', 'op_horror_movie', 'op_pizza_dinner', 'op_pineapple_pizza', 'op_cats_vs_dogs', 'op_weekend_home', 'co_another_country', 'co_superpower', 'co_riddle_hole', 'co_first_date', 'co_magic_room', 'co_time_travel', 'ki_specific_compliment', 'ki_small_thanks', 'ki_surprise_drink', 'ki_shoulder_massage', 'ki_shared_memory', 'ki_three_things', 'de_movie_night', 'de_dinner_tomorrow', 'de_weekend_plan', 'de_next_getaway', 'de_sunday_breakfast', 'co_eye_contact', 'ki_slow_dance', 'aa_first_impression', 'sm_unexpected_kiss', 'de_date_night');
