insert into public.missions (id, type, level, tags, message_a, message_b, follow_up, active)
values
  ('aa_math_joke', 'actor_audience'::public.mission_type, 1, array['humor']::text[], 'Conta esta piada a {parceiro}: ''Porque é que o livro de matemática está triste? Porque tem muitos problemas.'' Depois pergunta-lhe o que recebeu.', 'Daqui a pouco {parceiro} vai contar-te uma piada. Missão: ri-te de forma exageradíssima. Telemóvel em baixo para não falhares.', 'Telemóveis virados para baixo. Próxima ronda só daqui a uma hora.', true),
  ('aa_weird_week', 'actor_audience'::public.mission_type, 1, array['humor', 'conversa']::text[], 'Conta a {parceiro} a coisa mais estranha que te aconteceu esta semana. Tenta arrancar-lhe uma gargalhada.', '{parceiro} vai contar-te uma história. Missão: não te rias, aconteça o que acontecer.', 'Quem ganhou? Agora telemóveis em baixo.', true),
  ('aa_famous_impression', 'actor_audience'::public.mission_type, 1, array['humor']::text[], 'Imita uma pessoa famosa à tua escolha para {parceiro}, sem dizer quem é. Tens 3 tentativas para te fazeres entender.', '{parceiro} vai imitar alguém famoso. Missão: só podes acertar à terceira tentativa, mesmo que saibas logo quem é.', 'Revelem as missões um ao outro. Telemóveis em baixo.', true),
  ('aa_childhood_story', 'actor_audience'::public.mission_type, 1, array['conversa']::text[], 'Conta a {parceiro} uma história de quando eras criança que nunca lhe contaste.', 'Daqui a pouco {parceiro} vai contar-te uma história de infância. Missão: faz pelo menos 3 perguntas sobre essa história.', 'Agora é a vez de quem ouviu. Telemóveis em baixo.', true),
  ('aa_sell_object', 'actor_audience'::public.mission_type, 1, array['humor']::text[], 'Pega num objeto qualquer da sala e vende esse objeto a {parceiro} como se fosse o melhor produto do mundo.', '{parceiro} vai tentar vender-te alguma coisa. Missão: regateia o preço até ao ridículo.', 'Negócio fechado? Telemóveis em baixo.', true),
  ('aa_day_trailer', 'actor_audience'::public.mission_type, 1, array['humor', 'conversa']::text[], 'Descreve o teu dia a {parceiro} como se fosse o trailer de um filme de ação. Voz grave obrigatória.', '{parceiro} vai apresentar-te um trailer. No fim, dá uma nota de 0 a 10 e faz uma crítica de cinema a sério.', 'Fim da sessão. Telemóveis em baixo.', true),
  ('sm_ananas', 'secret_mission'::public.mission_type, 1, array['jogo']::text[], 'Missão secreta: nos próximos 15 minutos consegue que {parceiro} diga a palavra ''ananás''. Sem a dizeres tu.', 'Desconfia de todas as perguntas que {parceiro} te fizer nos próximos 15 minutos.', 'No fim, revelem as missões um ao outro.', true),
  ('sm_questions_only', 'secret_mission'::public.mission_type, 1, array['jogo', 'humor']::text[], 'Missão secreta: nos próximos 10 minutos, responde a tudo o que {parceiro} disser com uma pergunta. Aguenta o máximo possível.', 'Algo vai estar estranho na conversa com {parceiro}. Descobre o quê e diz "apanhei-te!"', 'Revelem as missões um ao outro. Telemóveis em baixo.', true),
  ('sm_hum_a_song', 'secret_mission'::public.mission_type, 1, array['jogo', 'musica']::text[], 'Missão secreta: consegue que {parceiro} cante ou trauteie uma música nos próximos 15 minutos. Sem pedires diretamente.', 'Nos próximos 15 minutos, cuidado com tudo o que soar a música.', 'No fim, revelem as missões um ao outro.', true),
  ('sm_penguin', 'secret_mission'::public.mission_type, 1, array['jogo']::text[], 'Missão secreta: usa a palavra ''pinguim'' 3 vezes na conversa com {parceiro} sem que pareça estranho.', '{parceiro} tem uma palavra secreta para dizer várias vezes. Descobre qual é.', 'Descobriram? Contem tudo um ao outro e pousem os telemóveis.', true),
  ('sm_high_five', 'secret_mission'::public.mission_type, 1, array['jogo']::text[], 'Missão secreta: consegue um ''mais cinco'' de {parceiro} nos próximos 10 minutos sem pedires diretamente.', 'Nos próximos 10 minutos, {parceiro} vai tentar levar-te a fazer um gesto. Não caias.', 'No fim, revelem as missões um ao outro.', true),
  ('sm_mirror', 'secret_mission'::public.mission_type, 1, array['jogo']::text[], 'Missão secreta: imita discretamente os gestos de {parceiro} durante 5 minutos. Ganhas se não deres nas vistas.', 'Repara bem nos movimentos de {parceiro} nos próximos minutos. Algo não bate certo.', 'Revelem as missões um ao outro. Telemóveis em baixo.', true),
  ('op_horror_movie', 'opposing'::public.mission_type, 1, array['filme']::text[], 'Convence {parceiro} a ver um filme de terror hoje. Tens 3 argumentos.', '{parceiro} vai tentar convencer-te de algo. Resiste até ouvires pelo menos 3 argumentos.', 'Decidam juntos e pousem os telemóveis.', true),
  ('op_pizza_dinner', 'opposing'::public.mission_type, 1, array['comida']::text[], 'Defende junto de {parceiro} que o jantar de amanhã deve ser pizza. Usa os melhores argumentos que tiveres.', '{parceiro} vai propor-te o jantar de amanhã. Defende outra opção qualquer até ao fim.', 'Cheguem a acordo a falar. Telemóveis em baixo.', true),
  ('op_pineapple_pizza', 'opposing'::public.mission_type, 1, array['comida', 'humor']::text[], 'Defende perante {parceiro} que ananás na pizza é a melhor invenção culinária de sempre.', '{parceiro} vai defender uma opinião culinária polémica. O teu papel: discordar com toda a convicção.', 'Quem venceu o debate? Telemóveis em baixo.', true),
  ('op_cats_vs_dogs', 'opposing'::public.mission_type, 1, array['humor']::text[], 'Convence {parceiro} de que os gatos são melhores do que os cães. Tens 2 minutos.', '{parceiro} vai tentar convencer-te de algo sobre animais. Defende o lado contrário, seja qual for.', 'Empate técnico. Telemóveis em baixo.', true),
  ('op_weekend_home', 'opposing'::public.mission_type, 1, array['planos']::text[], 'Convence {parceiro} a passarem o próximo fim de semana sem sair de casa.', '{parceiro} tem um plano para o fim de semana. Contrapropõe uma aventura fora de casa.', 'Encontrem um meio-termo a falar. Telemóveis em baixo.', true),
  ('co_another_country', 'coop'::public.mission_type, 1, array['conversa', 'viagem']::text[], 'Tens metade de uma pergunta: ''Se pudéssemos viver um ano noutro país...''', 'Tens a outra metade: ''...qual seria e o que farias lá primeiro?'' Juntem as metades e respondam os dois.', 'Telemóveis em baixo, a conversa é vossa.', true),
  ('co_superpower', 'coop'::public.mission_type, 1, array['conversa']::text[], 'Tens metade de uma pergunta: ''Se pudesses ter um superpoder durante um dia...''', 'Tens a outra metade: ''...qual escolherias e o que farias primeiro?'' Juntem as metades e respondam os dois.', 'Telemóveis em baixo, a conversa é vossa.', true),
  ('co_riddle_hole', 'coop'::public.mission_type, 1, array['enigma']::text[], 'Tens uma adivinha: ''Quanto mais se tira, maior fica. O que é?'' {parceiro} tem a pista. Resolvam juntos.', 'Tens a pista de uma adivinha que {parceiro} recebeu: ''Pode estar no chão ou no jardim.'' Resolvam juntos.', 'Era um buraco. Telemóveis em baixo.', true),
  ('co_first_date', 'coop'::public.mission_type, 1, array['conversa', 'memorias']::text[], 'Tens metade de uma pergunta: ''Do nosso primeiro encontro, qual é o pormenor...''', 'Tens a outra metade: ''...de que te lembras e achas que a outra pessoa já esqueceu?'' Juntem as metades e respondam os dois.', 'Telemóveis em baixo, a conversa é vossa.', true),
  ('co_magic_room', 'coop'::public.mission_type, 1, array['conversa', 'criativo']::text[], 'Tens metade de uma pergunta: ''Se a nossa casa pudesse ter uma divisão mágica...''', 'Tens a outra metade: ''...o que teria lá dentro?'' Juntem as metades e desenhem essa divisão num papel.', 'Papel e caneta, telemóveis em baixo.', true),
  ('co_time_travel', 'coop'::public.mission_type, 1, array['conversa', 'memorias']::text[], 'Tens metade de uma pergunta: ''Se pudéssemos voltar a um dia que vivemos juntos...''', 'Tens a outra metade: ''...qual escolheríamos e porquê?'' Juntem as metades e respondam os dois.', 'Telemóveis em baixo, a conversa é vossa.', true),
  ('ki_specific_compliment', 'kindness'::public.mission_type, 1, array['elogio']::text[], 'Faz a {parceiro} um elogio sobre algo concreto que fez esta semana.', 'Vais ouvir algo simpático em breve. Tenta adivinhar se a ideia foi de {parceiro} ou da app.', 'Agora é convosco.', true),
  ('ki_small_thanks', 'kindness'::public.mission_type, 1, array['elogio']::text[], 'Agradece a {parceiro} uma coisa pequena que fez recentemente e que talvez ache que não reparaste.', 'Daqui a pouco {parceiro} vai dizer-te uma coisa simpática. Missão: aceita sem desvalorizar.', 'Agora é convosco. Telemóveis em baixo.', true),
  ('ki_surprise_drink', 'kindness'::public.mission_type, 1, array['gesto']::text[], 'Prepara uma bebida para {parceiro} sem perguntar o que quer. Aposta no que achas que prefere.', 'Vem aí uma surpresa de {parceiro}. Missão: adivinha o que é antes de chegar.', 'Acertou? Bebam com calma e sem telemóveis.', true),
  ('ki_shoulder_massage', 'kindness'::public.mission_type, 1, array['gesto']::text[], 'Oferece a {parceiro} uma massagem de 2 minutos nos ombros. Sem pedir nada em troca.', 'Algo de bom vem aí. Telemóvel em baixo e mãos livres.', 'Agora é convosco.', true),
  ('ki_shared_memory', 'kindness'::public.mission_type, 1, array['memorias']::text[], 'Conta a {parceiro} uma memória vossa de que gostas muito e explica porquê.', '{parceiro} vai partilhar uma memória contigo. No fim, conta uma tua também.', 'Telemóveis em baixo, a conversa é vossa.', true),
  ('ki_three_things', 'kindness'::public.mission_type, 1, array['elogio']::text[], 'Diz a {parceiro} três coisas que admiras na sua maneira de ser.', 'Vais ouvir três coisas simpáticas. Missão: responde com uma tua.', 'Agora é convosco.', true),
  ('de_movie_night', 'decision'::public.mission_type, 1, array['filme']::text[], 'Hoje é noite de filme. Propõe três géneros a {parceiro}, que elimina um. Escolham a partir dos que sobram.', '{parceiro} vai propor-te uma noite de filme. Tu escolhes o snack.', 'Escolham a falar, não a fazer scroll.', true),
  ('de_dinner_tomorrow', 'decision'::public.mission_type, 1, array['comida']::text[], 'Propõe a {parceiro} três opções para o jantar de amanhã. A escolha final não é tua.', '{parceiro} vai dar-te 3 opções para o jantar de amanhã. Escolhe uma, mas só depois de ouvires as três.', 'Decidido. Telemóveis em baixo.', true),
  ('de_weekend_plan', 'decision'::public.mission_type, 1, array['planos']::text[], 'Propõe a {parceiro} três planos para o próximo fim de semana: um calmo, um aventureiro e um absurdo.', '{parceiro} vai propor-te planos para o fim de semana. Elimina um e escolham juntos entre os outros dois.', 'Plano feito. Telemóveis em baixo.', true),
  ('de_next_getaway', 'decision'::public.mission_type, 1, array['viagem', 'planos']::text[], 'Sugere a {parceiro} três destinos para a próxima escapadinha. Nada de pesquisar no telemóvel.', '{parceiro} tem 3 destinos para uma escapadinha. Faz uma pergunta sobre cada um antes de escolher.', 'Sonhem a falar, pesquisem amanhã. Telemóveis em baixo.', true),
  ('de_sunday_breakfast', 'decision'::public.mission_type, 1, array['comida', 'planos']::text[], 'Propõe a {parceiro} três ideias de pequeno-almoço para domingo.', '{parceiro} vai propor-te um pequeno-almoço especial. Escolhe uma ideia e decidam quem trata de quê.', 'Domingo resolvido. Telemóveis em baixo.', true),
  ('co_eye_contact', 'coop'::public.mission_type, 2, array['romantico']::text[], 'Desafio: olharem-se nos olhos durante 1 minuto, sem falar. Propõe a {parceiro} e começa a contar.', '{parceiro} vai propor-te um desafio de 1 minuto. Aceita e tenta não te rir.', 'Agora é convosco.', true),
  ('ki_slow_dance', 'kindness'::public.mission_type, 2, array['romantico', 'musica']::text[], 'Põe uma música calma e convida {parceiro} para dançar na sala. Um minuto chega.', 'Daqui a pouco vais receber um convite de {parceiro}. Diz que sim.', 'A música continua, os telemóveis não.', true),
  ('aa_first_impression', 'actor_audience'::public.mission_type, 2, array['romantico', 'memorias']::text[], 'Conta a {parceiro} o que pensaste da primeira vez que se viram. Com toda a sinceridade.', '{parceiro} vai contar-te algo sobre o dia em que se conheceram. Depois é a tua vez.', 'Telemóveis em baixo, a conversa é vossa.', true),
  ('sm_unexpected_kiss', 'secret_mission'::public.mission_type, 2, array['romantico']::text[], 'Missão secreta: dá um beijo a {parceiro} num sítio inesperado (testa, nariz, mão) nos próximos 10 minutos.', 'Nos próximos 10 minutos, fica de olho em {parceiro}. Anda a tramar alguma.', 'Agora é convosco.', true),
  ('de_date_night', 'decision'::public.mission_type, 2, array['romantico', 'planos']::text[], 'Propõe a {parceiro} três ideias para um encontro a dois este mês, como se fosse o primeiro.', '{parceiro} vai convidar-te para um encontro. Escolhe uma das ideias e marquem a data já, a falar.', 'Encontro marcado. Telemóveis em baixo.', true)
